function smartHomeRoleDecision(content,c){if(!smartHomeRoleAvailable(c))return null;const tags=smartHomeRoleTags(content);if(!tags.length)return null;if(tags.length!==1)return{valid:false,message:'角色一次给出了多个灯控动作，未执行',tagCount:tags.length};const body=tags[0].replace(/^[\[【]|[\]】]$/g,'').split(/[|｜]/).slice(2),raw={};for(const item of body){const m=String(item||'').trim().match(/^([a-zA-Z]+)\s*=\s*([^=]+)$/);if(!m)return{valid:false,message:'角色灯控参数格式不完整',tagCount:1};const key=m[1].toLowerCase(),value=m[2].trim();if(Object.prototype.hasOwnProperty.call(raw,key))return{valid:false,message:'角色灯控参数重复',tagCount:1};raw[key]=value;}const allowed=new Set(['power','brightness','color','hue','saturation','warmth']);if(Object.keys(raw).some(key=>!allowed.has(key)))return{valid:false,message:'角色灯控动作超出白名单',tagCount:1};const plan={};if(raw.power!==undefined){if(!/^(?:on|off)$/i.test(raw.power))return{valid:false,message:'角色开关参数无效',tagCount:1};plan.power=raw.power.toLowerCase();}if(raw.color!==undefined){const named=smartHomeRoleNamedColor(raw.color);if(!named)return{valid:false,message:'角色命名颜色不在允许范围内',tagCount:1};plan.color=named.key;}for(const key of ['brightness','hue','saturation','warmth'])if(raw[key]!==undefined){const n=Number(raw[key]);if(!Number.isFinite(n))return{valid:false,message:'角色灯控数值无效',tagCount:1};plan[key]=n;}const hue=plan.hue!==undefined,saturation=plan.saturation!==undefined,named=plan.color!==undefined?smartHomeRoleNamedColor(plan.color):null;if(hue!==saturation||plan.warmth!==undefined&&(hue||named)||named&&hue||plan.power==='off'&&Object.keys(plan).length>1||plan.brightness!==undefined&&(plan.brightness<1||plan.brightness>100)||hue&&(plan.hue<0||plan.hue>360||plan.saturation<0||plan.saturation>100)||plan.warmth!==undefined&&(plan.warmth<0||plan.warmth>100)||!Object.keys(plan).length)return{valid:false,message:'角色灯控组合不在允许范围内',tagCount:1};const intended=named||hue?{hue:named?named.hue:plan.hue,saturation:named?named.saturation:plan.saturation}:null;if(intended&&smartHomeRoleColorMismatch(smartHomeRoleStripTags(content),intended))return{valid:false,message:'角色说出的颜色与灯控参数不一致，未执行',tagCount:1};return{valid:true,plan,tagCount:1};}
function smartHomeRoleStateText(state){if(!state||typeof state!=='object')return'没有可用的最终状态';const rows=['电源'+(state.power===true?'已开':state.power===false?'已关':'未知')],actual=smartHomeRoleActualColor(state);if(Number.isFinite(Number(state.brightness)))rows.push('亮度'+Math.round(Number(state.brightness))+'%');if(actual)rows.push('实际颜色'+actual.label+'（色相'+Math.round(Number(state.hue))+'、饱和度'+Math.round(Number(state.saturation))+'）');else if(Number.isFinite(Number(state.hue))&&Number.isFinite(Number(state.saturation)))rows.push('色相'+Math.round(Number(state.hue))+'、饱和度'+Math.round(Number(state.saturation)));if(Number.isFinite(Number(state.warmth)))rows.push('色温值'+Math.round(Number(state.warmth)));return rows.join('，');}
function smartHomeRoleFalseSuccess(text){const t=String(text||'').replace(/[\[【][^\]】]*[\]】]/g,'');if(/(?:没|没有|未|不能|没能|失败|不成功|没成功|无法|不确定|不能确认)/.test(t))return false;return /(?:已经|已|给你|我把|现在).{0,16}(?:打开|开了|关掉|关了|调到|调成|换成|设成|弄好|调好)/.test(t);}
