companionRolePrompt=function(c){let p=companionRolePromptCore(c);const st=S.couple&&companionState();if(!p||!st||!st.roleAccess)return p;if(!companionReady(st))return p.replace('位置或足迹','位置、足迹、电量或健康摘要');const per=st.permissions||{};if(per.battery&&st.battery)p+='\n· 外置 iPhone 当前电量：'+Math.round(st.battery.level*100)+'%，'+st.battery.state+(st.battery.lowPower?'，低电量模式已开启':'')+'；更新时间 '+(st.battery.ts?fmtDT(st.battery.ts):'未知')+'。';if(per.health&&st.health){const h=st.health;p+='\n· 用户明确授权的 HealthKit/Apple Watch 健康摘要：'+companionHealthSummary(h)+'；更新时间 '+(h.ts?fmtDT(h.ts):'未知')+'。';if(h.stateOfMind)p+=' 最近心境是用户主动记录的数据，标签：'+(h.stateOfMind.labels.join('、')||'无')+'；不得说成自动情绪识别。';p+=' 健康数据只用于陪伴提示，不能诊断疾病、推断未记录的情绪或替代医生。心率升高或降低不能证明撒谎、哭泣、背叛或任何具体情绪；只能结合对方亲口说的话表达关心。';}p+='\n· 以上被授权的最新数据可以在对话确有需要时主动查看，不必等'+S.me.name+'先问；但不要每轮机械播报，也不能把过期快照说成实时状态。';return p;};
const companionRolePromptWellness=companionRolePrompt;
companionRolePrompt=function(c){let p=companionRolePromptWellness(c);const st=S.couple&&companionState();if(!p||!st||!st.roleAccess||!companionReady(st))return p;p+='\n· 查看次数规则：心率、电量和位置在对应权限开启后可按关系与上下文全天自主查看，不限次数；睡眠与今日步数作为同一次 HealthKit 每日必查，今日总屏幕时长和全部逐 App 使用记录作为另一次每日必查，各自每天只查看一次，只能在用户设置的时段内查看。“早安/早上好”可以让当天睡眠与步数立即查看一次，但同一天不会重复。';if(!st.permissions.appControl)return p;p+='\n· 锁定目标完整性：真实 iPhone 的锁定/解锁必须按外置 App 名称与稳定 ID 精确执行。限额关联到不同名称的小手机虚拟 App，并不授权拿那个虚拟 App 替代真实目标；只有同名且两边均授权时才同步锁定内外两端。命令刚提交时只能自然地说“已经交给 iPhone 执行，正在等它确认”；收到设备回执且新快照明确为已锁后，才可以断言“已经锁上”。网页接受命令不等于设备执行成功。';return p;};
const companionRolePromptLockLedgerCore=companionRolePrompt;
companionRolePrompt=function(c){let p=companionRolePromptLockLedgerCore(c),st=S.couple&&companionState();if(!p||!st||!st.roleAccess||!companionReady(st))return p;const usageFresh=companionUsageSnapshotFresh(st,Date.now(),20*60000),lockRows=(st.apps||[]).map(app=>app.name+'：期望'+(companionDesiredLocked(st,app)?'锁定':'可用')+'，设备回报'+(app.reportedLocked===true||app.locked===true?'已锁':'可用')+(typeof lockUntilRoleNote==='function'?lockUntilRoleNote('ext:'+app.id):'')).join('；');p+='\n· 使用量快照：'+(usageFresh?'当前日期且新鲜，生成于 '+fmtDT(st.usageGeneratedAt):'不是20分钟内的当前日期新鲜数据，不得触发每日使用量查看，也不得把最近的控制回执时间当作使用量更新时间')+'。';if(lockRows)p+='\n· 锁定双状态：'+lockRows+'。期望状态只会被明确的锁定/解锁动作修改；设备快照只能更新设备回报，不能自行授权解锁。';return p;};
const companionRolePromptExternalDataCore=companionRolePrompt;
/* 指令解析器以前只知道「可操作的 App 有哪些」，完全不知道谁已经锁着，所以会把
   "抖音还锁着呢" 这种陈述再解析成一次锁定。这份台账专门喂给它。 */
function companionControlLedgerForParser(){const rows=[];try{const st=companionState();for(const app of (st&&st.apps)||[]){if(!app||!app.name)continue;rows.push('· '+app.name+'：'+(app.locked===true||app.reportedLocked===true?'当前已锁'+(typeof lockUntilRoleNote==='function'?lockUntilRoleNote('ext:'+app.id):''):'当前可用'));}const locks=(S.couple&&S.couple.locks)||{},gr=(S.couple&&S.couple.grant)||{};for(const k of Object.keys(gr)){if(!gr[k]||!LOCKABLE[k])continue;if(rows.some(r=>r.indexOf('· '+LOCKABLE[k]+'：')===0))continue;rows.push('· '+LOCKABLE[k]+'：'+(locks[k]?'当前已锁'+(typeof lockUntilRoleNote==='function'?lockUntilRoleNote('int:'+k):''):'当前可用'));}}catch(_){}return rows.length?'\n【这些 App 现在的真实状态】\n'+rows.join('\n'):'';}
function companionRoleControlLedger(config){const rows=[];for(const app of (config&&config.apps)||[]){if(!app||!app.name)continue;const state=companionExternalCommandState(config,app,Date.now());let text='状态尚不能确认';if(state.kind==='pendingUnlock')text='解锁命令已提交，正在等待 iPhone 回执，不能说已经解开';else if(state.kind==='pendingLock')text='锁定命令已提交，正在等待 iPhone 回执，不能说已经锁好';else if(state.kind==='awaitSnapshot')text='设备已经回执，正在等待回执后的新快照，不能断言最终状态';else if(state.kind==='confirmed')text='已由回执后的新快照确认'+(app.locked?'锁定':'可用');else if(state.kind==='snapshot')text='当前设备快照显示'+(app.locked?'锁定':'可用');else if(state.kind==='failed'||state.kind==='expired'||state.kind==='conflict')text=state.text+'，不得把失败或冲突说成成功';else if(state.kind==='snapshotStale')text=state.text+'，只能称为上次状态';rows.push('· '+app.name+'：'+text);}return rows.join('\n');}
function companionRoleControlOnlyPrompt(c,config){
  let p='\n\n# 真实 iPhone 查看硬规则（最高优先级）\n你有权在授权范围内查看和控制这台 iPhone，但当前对话【没有本次读取编号，也没有执行新的设备采集】。因此你现在不知道电量、屏幕使用时间、逐 App 时长、步数、睡眠、心率、心电、HRV 或位置的当前结果。不得读取或复述情侣空间里的伴生缓存、旧聊天里的数值、限额或虚拟手机数据；尤其不得说“没刷新、没刷出来、没同步、没戴手表、读取不到”等假装已经查看过的话。你若自然决定查看，必须先明确说要查看具体项目；程序会启动顶部逐项进度和原生读取，读取结束后你才能依据本次结果回答。';
  if(!companionReady(config))return p+'\n真实 iPhone 尚未绑定，不能输出锁定、解锁或限额标签，也不能声称操作成功。';
  const per=config.permissions||{},names=(config.apps||[]).map(x=>String(x&&x.name||'').trim()).filter(Boolean);
  if(per.appControl&&names.length){const ledger=typeof companionRoleControlLedger==='function'?companionRoleControlLedger(config):'';p+='\n【真实控制能力仍然有效】当前按稳定 ID 可控制的 App：'+names.join('、')+'。\n【当前 App 控制台账】这不是屏幕时长读取，可以在普通聊天中直接作为控制事实使用：\n'+(ledger||'· 暂无可核对状态')+'\n说“还没解、仍锁着、已经解开、已经锁好”必须符合这份台账；旧聊天和旧记忆不能覆盖它。\n【全部控制定义】“全部锁定、全部解锁、解除全锁、所有软件、全部 App”固定表示同时处理两组目标：小手机中已经授权给你的全部内置 App，以及真实 iPhone 当前全部已选 App。不能把它缩成仅内置或仅外置。单个或部分目标仍使用 [锁定|准确App名|仅外置] / [解锁|准确App名|仅外置]；全量操作统一使用 [锁定|全部内外 App|内外同时] / [解锁|全部内外 App|内外同时]。动作引擎会忽略错误的单端范围并按内外两组完整执行。命令提交后只能说已经交给 iPhone 执行、正在等确认；设备回执和新快照确认前绝不能谎称已经锁好。\n【说和做分开】口头说法（包括威胁、讲条件、开玩笑、以后再说）永远不会控制 iPhone，只有指令标签会执行；没真的决定就不要写指令，想怎么说都可以。';}
  else if(per.appControl)p+='\n当前没有已同步的稳定 App ID，不能声称锁定或解锁了任何软件。';
  if(per.limits)p+='\n每日限额仍只允许对已完成内外绑定的 App 使用 [限时|准确App名|分钟数|内外同时]；缺少绑定时不执行。';
  return p;
}
companionRolePrompt=function(c,opt){const config=S.couple&&c&&S.couple.cid===c.id?companionState():null,inspection=!!(opt&&opt.companionInspection);if(!config||!config.roleAccess)return'';if(!inspection)return companionRoleControlOnlyPrompt(c,config);const external=companionRoleDataState();if(!external)return'\n\n# 真实 iPhone 查看硬规则（最高优先级）\n本次原生采集尚未返回读取编号，不能用任何缓存代替，也不能猜测成功或失败。';const original=S.couple.companion;S.couple.companion=external;try{return companionRolePromptExternalDataCore(c);}finally{S.couple.companion=original;}};
const companionRolePromptAllControlCore=companionRolePrompt;
