function companionAutomationDay(ts){const d=new Date(ts||Date.now());return d.getFullYear()+'-'+String(d.getMonth()+1).padStart(2,'0')+'-'+String(d.getDate()).padStart(2,'0');}
function companionAutomationClock(value,fallback){const m=String(value||'').match(/^(\d{1,2}):(\d{2})$/),h=m?+m[1]:-1,n=m?+m[2]:-1;return h>=0&&h<24&&n>=0&&n<60?String(h).padStart(2,'0')+':'+String(n).padStart(2,'0'):fallback;}
function companionAutomationMinute(value){const v=companionAutomationClock(value,'00:00').split(':');return +v[0]*60+(+v[1]);}
function companionAutomationWindow(now,start,end){const d=new Date(now||Date.now()),minute=d.getHours()*60+d.getMinutes(),from=companionAutomationMinute(start),to=companionAutomationMinute(end),overnight=from>to,inside=from===to?true:overnight?(minute>=from||minute<to):(minute>=from&&minute<to);if(inside&&overnight&&minute<to)d.setDate(d.getDate()-1);return {inside,day:companionAutomationDay(d.getTime()),from,to,overnight};}
function companionAutomationGoodMorning(text){return /^(?:早安|早上好|早呀|早啊|早哦|早～|早~)/.test(String(text||'').trim());}
function companionAutomationRangeText(start,end){return companionAutomationClock(start,'00:00')+'–'+companionAutomationClock(end,'00:00');}
function companionSaveAutomationWindows(){const st=companionState(),get=id=>{const el=document.getElementById(id);return el&&el.value||'';},sleepStart=companionAutomationClock(get('comp_auto_sleep_start'),''),sleepEnd=companionAutomationClock(get('comp_auto_sleep_end'),''),usageStart=companionAutomationClock(get('comp_auto_usage_start'),''),usageEnd=companionAutomationClock(get('comp_auto_usage_end'),'');if(!sleepStart||!sleepEnd||!usageStart||!usageEnd){toast('请把两个开始和结束时间都填完整');return false;}if(sleepStart===sleepEnd||usageStart===usageEnd){toast('开始时间和结束时间不能相同');return false;}st.automationWindows={sleepStart,sleepEnd,usageStart,usageEnd};st.automations.morningSleep=true;st.automations.eveningScreen=true;save();render();toast('每日必查时段已保存');return true;}
function companionAutomationFresh(ts,maxAge,now){return Number.isFinite(+ts)&&+ts>0&&now-(+ts)>=0&&now-(+ts)<=maxAge;}
